UPDATE account_state SET account_state = (
  SELECT i.previous_state FROM account_export_item i
  WHERE i.job_id = #{id} AND i.account_id = account_state.account_id AND i.tenant_id = account_state.tenant_id
), state_source = 'EXPORT_CANCELLED', updated_at = #{now}, last_state_sync_time = #{now}
WHERE account_state = 4 AND state_source = 'ACCOUNT_EXPORT'
  AND account_id IN (SELECT i.account_id FROM account_export_item i WHERE i.job_id = #{id})
